import { type Result, ok, err } from './result.ts';

export interface NoteInput { title: string; body: string }

function parseJson(raw: string): Result<unknown> {
  try {
    return ok(JSON.parse(raw) as unknown);
  } catch {
    return err('invalid JSON');
  }
}

export function parseNoteInput(raw: string): Result<NoteInput> {
  const parsed = parseJson(raw);
  if (!parsed.ok) return err(parsed.error);
  const v = parsed.value;
  if (typeof v !== 'object' || v === null || Array.isArray(v)) return err('body must be an object');
  const { title, body = '' } = v as Record<string, unknown>;
  if (typeof title !== 'string') return err('title must be a string');
  if (typeof body !== 'string') return err('body must be a string');
  return ok({ title, body });
}
