    if (m) return send(200,","originalFile":"import test from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import { once } from 'node:events';

type Note = { id: number; title: string; body: string };

function fake(broken: boolean, badGet = false): http.Server {
  const notes: Note[] = [];
  return http.createServer((req, res) => {
    const send = (s: number, b: unknown) => {
      res.writeHead(s, { 'content-type': 'application/json' });
      res.end(JSON.stringify(b));
    };
    const url = new URL(req.url ?? '/', 'http://x');
    if (url.pathname === '/health') return send(broken ? 500 : 200, { status: 'ok' });
    if (req.method === 'POST' && url.pathname === '/notes') {
      let d = '';
      req.on('data', (c) => (d += c));
      req.on('end', () => {
        const n = { id: notes.length + 1, ...JSON.parse(d) } as Note;
        notes.push(n);
        send(201, n);
      });
      return;
    }
    const m = /^\/notes\/(\d+)$/.exec(url.pathname);
    if (m) return send(200, notes.find((n) => n.id === Number(m[1])));
    if (url.pathname === '/search') {
      const q = (url.searchParams.get('q') ?? '').toLowerCase();
      return send(200, notes.filter((n) => n.title.toLowerCase().includes(q)));
    }
    send(404, { error: 'not found' });
  });
}

async function runSmoke(server: http.Server | null) {
  let url = 'http://127.0.0.1:1';
  if (server) {
    server.listen(0);
    await once(server, 'listening');
    url = `http://127.0.0.1:${(server.address() as { port: number }).port}`;
  }
  const r = await new Promise<{ status: number | null; out: string }>((resolve) => {
    import('node:child_process').then(({ spawn }) => {
      const p = spawn('node', ['scripts/smoke.ts'], { env: { ...process.env, SMOKE_URL: url } });
      let out = '';
      p.stdout.on('data', (c) => (out += c));
      p.stderr.on('data', (c) => (out += c));
      p.on('close', (status) => resolve({ status, out }));
    });
  });
  server?.close();
  return r;
}

test('AC-18 smoke passes against a healthy service', async () => {
  const r = await runSmoke(fake(false));
  assert.equal(r.status, 0, r.out);
});

test('AC-18 package.json defines npm run smoke', async () => {
  const { default: pkg } = await import('../package.json', { with: { type: 'json' } });
  assert.equal(pkg.scripts.smoke, 'node scripts/smoke.ts');
});

test('AC-19 smoke exits non-zero and names the failing step', async () => {
  const r = await runSmoke(fake(true));
  assert.notEqual(r.status, 0);
  assert.match(r.out, /health/i);
});

test('AC-19 smoke exits non-zero when unreachable', async () => {
  const r = await runSmoke(null);
  assert.notEqual(r.status, 0);
  assert.match(r.out, /health/i);
});

test('AC-19 smoke names a later failing step when body is not JSON', async () => {
  const r = await runSmoke(fake(false, true));
  assert.notEqual(r.status, 0);
  assert.match(r.out, /get note/i);
});
