import http from 'node:http';
import type { IncomingMessage, ServerResponse, Server } from 'node:http';
import type { NoteStore } from './note-store.ts';
import type { Result } from './result.ts';
import { routes, type Route } from './http-routes.ts';

export interface ServerOptions {
  store: NoteStore;
  log?: (line: string) => void;
}

function send(res: ServerResponse, status: number, payload: unknown): void {
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(payload));
}

function respond(res: ServerResponse, route: Route, result: Result<unknown>): void {
  if (result.ok) send(res, route.okStatus, result.value);
  else send(res, route.errStatus, { error: result.error });
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (c: Buffer) => chunks.push(c));
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function match(method: string, pathname: string): { route: Route; params: string[] } | undefined {
  for (const route of routes) {
    const m = route.method === method ? route.pattern.exec(pathname) : null;
    if (m) return { route, params: m.slice(1) };
  }
  return undefined;
}

async function handle(req: IncomingMessage, res: ServerResponse, store: NoteStore, url: URL): Promise<void> {
  const found = match(req.method ?? '', url.pathname);
  const raw = await readBody(req);
  if (!found) return send(res, 404, { error: 'not found' });
  const result = found.route.handle({ store, raw, params: found.params, query: url.searchParams });
  respond(res, found.route, result);
}

export function createServer({ store, log = console.log }: ServerOptions): Server {
  return http.createServer((req, res) => {
    const start = performance.now();
    const url = new URL(req.url ?? '/', 'http://localhost');
    res.on('finish', () => {
      const ms = Math.round(performance.now() - start);
      log(`${req.method} ${url.pathname} ${res.statusCode} ${ms}ms`);
    });
    handle(req, res, store, url).catch(() => {
      if (!res.headersSent) send(res, 500, { error: 'internal error' });
      else res.end();
    });
  });
}
import type { NoteStore } from './note-store.ts';
import { searchNotes } from './search.ts';
import { type Result, ok, err } from './result.ts';
import { parseNoteInput } from './json-body.ts';

export interface RouteRequest {
  store: NoteStore;
  raw: string;
  params: string[];
  query: URLSearchParams;
