const p95 = (xs: number[]) => [...xs].sort((a, b) => a - b)[Math.ceil(xs.length * 0.95) - 1];

test('AC-14 p95 latency under 50ms per endpoint with 1000 notes', async () => {
  const store = new NoteStore();
  for (let i = 0; i < 1000; i++) store.add(`title ${i}`, `body ${i}`);
  const server = createServer({ store, log: () => {} });
  await new Promise<void>((r) => server.listen(0, r));
  const url = `http://localhost:${(server.address() as AddressInfo).port}`;
  const calls: [string, string, string?][] = [
    ['GET', '/health'], ['GET', '/notes'], ['GET', '/notes/500'], ['GET', '/search?q=title'],
    ['POST', '/notes', '{"title":"t","body":"b"}'],
  ];
  try {
    for (const [method, path, body] of calls) {
      const times: number[] = [];
      for (let i = 0; i < 100; i++) {
        const s = performance.now();
        await (await fetch(url + path, { method, body })).text();
        times.push(performance.now() - s);
      }
      assert.ok(p95(times) < 50, `${method} ${path} p95 ${p95(times)}ms`);
    }
  } finally { server.close(); }
});
